#include <iostream>
#include <string>
#include <cctype>
using namespace std;

int main() {
    int n;
    string a;
    cin >> n >> a;

    bool seen[26] = {};
    int count = 0;

    for (unsigned char c : a) {
        c = static_cast<unsigned char>(tolower(c));
        if (!seen[c - 'a']) {
            seen[c - 'a'] = true;
            ++count;
        }
    }

    cout << (count == 26 ? "YES" : "NO") << '\n';
    return 0;
}

#include <iostream>
#include <string>
#include <cctype>
using namespace std;

int main() {
    int n;
    string s;
    cin >> n >> s;

    bool seen[26] = {};
    int distinct = 0;

    for (unsigned char c : s) {
        int index = tolower(c) - 'a';
        if (!seen[index]) {
            seen[index] = true;
            ++distinct;
        }
    }

    cout << (distinct == 26 ? "YES" : "NO") << '\n';
    return 0;
}

#include <iostream>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    int n;
    string a;
    cin >> n >> a;

    transform(a.begin(), a.end(), a.begin(),
              [](unsigned char c) { return tolower(c); });

    sort(a.begin(), a.end());
    a.erase(unique(a.begin(), a.end()), a.end());

    cout << (a.size() == 26 ? "YES" : "NO") << '\n';
    return 0;
}

